import{randomIndex}from'./tools-core.mjs';import{diffLines,zonedParts,resolveZoned,wheelLanding,coolText}from'./tools-extra-core.mjs';
const root=document.querySelector('[data-tool]'),kind=root?.dataset.tool,q=s=>root.querySelector(s),get=id=>document.getElementById(id),value=id=>get(id).value;
const message=(s,error=false)=>{const o=q('[data-result]');o.textContent=s;o.dataset.error=String(error)};
const copy=async(text,target)=>{try{await navigator.clipboard.writeText(text);target.textContent='已複製。'}catch{target.textContent='無法自動複製，請選取文字手動複製。'}};
if(kind==='clock'){const render=()=>{const date=new Date(),zone=value('clock-zone'),t=q('[data-clock]');t.dateTime=date.toISOString();t.textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:get('clock-12').checked}).format(date);q('[data-clock-date]').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:zone,year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(date)};render();const ticker=setInterval(render,250);get('clock-zone').addEventListener('change',render);get('clock-12').addEventListener('change',render);q('[data-clock-fullscreen]').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await q('[data-clock-display]').requestFullscreen()}catch{message('此瀏覽器不支援全螢幕，仍可正常看時間。')}});window.addEventListener('pagehide',()=>clearInterval(ticker))}
if(kind==='scoreboard'){let scores=[0,0],history=[];const paint=()=>{root.querySelectorAll('[data-score]').forEach((o,i)=>o.textContent=scores[i]);q('[data-score-undo]').disabled=!history.length;root.querySelectorAll('[data-score-delta="-1"]').forEach(b=>b.disabled=!get('score-negative').checked&&scores[+b.dataset.team]<=0)};const change=(next,notice)=>{history.push([...scores]);if(history.length>100)history.shift();scores=next;paint();message(notice)};root.querySelectorAll('[data-score-delta]').forEach(b=>b.addEventListener('click',()=>{const step=Number(value('score-step'));if(!Number.isInteger(step)||step<1||step>100){message('每次加減需為 1 到 100 的整數。',true);return}const i=+b.dataset.team,next=[...scores];next[i]+=step*Number(b.dataset.scoreDelta);if(!get('score-negative').checked)next[i]=Math.max(0,next[i]);if(Math.abs(next[i])>999999){message('分數最多六位數。',true);return}change(next,value('team-'+i)+' '+next[i]+' 分。')}));q('[data-score-reset]').addEventListener('click',()=>change([0,0],'已歸零，可按復原恢復。'));q('[data-score-undo]').addEventListener('click',()=>{if(history.length)scores=history.pop();if(scores.some(s=>s<0))get('score-negative').checked=true;paint();message('已復原。')});get('score-negative').addEventListener('change',()=>{if(!get('score-negative').checked&&scores.some(s=>s<0))change(scores.map(s=>Math.max(0,s)),'已將負分調回零，可復原。');paint()});paint()}
if(kind==='text-diff'){q('[data-extra-form]').addEventListener('submit',e=>{e.preventDefault();try{const rows=diffLines(value('diff-before'),value('diff-after')),output=q('[data-diff-output]');output.replaceChildren();for(const row of rows){const line=document.createElement('div'),sign=document.createElement('span'),text=document.createElement(row.type==='add'?'ins':row.type==='remove'?'del':'span');line.className='diff-line '+row.type;sign.textContent=row.type==='add'?'+':row.type==='remove'?'−':' ';sign.setAttribute('aria-label',row.type==='add'?'新增':row.type==='remove'?'刪除':'相同');text.textContent=row.text||' ';line.append(sign,text);output.append(line)}const added=rows.filter(r=>r.type==='add').length,removed=rows.filter(r=>r.type==='remove').length;message(added||removed?`新增 ${added} 行，刪除 ${removed} 行。`:'兩段文字相同。')}catch(err){q('[data-diff-output]').replaceChildren();message(err.message,true)}});q('[data-diff-swap]').addEventListener('click',()=>{const before=value('diff-before');get('diff-before').value=value('diff-after');get('diff-after').value=before;q('[data-diff-output]').replaceChildren();message('已交換，按比較文字查看結果。')})}
if(kind==='timezone'){get('zone-time').value=zonedParts(new Date(),'Asia/Taipei');get('zone-to').value='America/New_York';q('[data-extra-form]').addEventListener('submit',e=>{e.preventDefault();try{const{instant,ambiguous}=resolveZoned(value('zone-time'),value('zone-from'),value('zone-fold')),format=zone=>new Intl.DateTimeFormat('zh-TW',{timeZone:zone,dateStyle:'full',timeStyle:'long',hour12:false}).format(instant);message(get('zone-to').selectedOptions[0].textContent+' '+format(value('zone-to'))+(ambiguous?'。原地時刻出現兩次，已依你選擇的順序換算。':''));const world=q('[data-world-times]');world.replaceChildren();for(const[zone,name]of[['Asia/Taipei','台北'],['Asia/Tokyo','東京'],['Europe/London','倫敦'],['America/New_York','紐約']]){const row=document.createElement('p'),label=document.createElement('strong'),time=document.createElement('span');label.textContent=name;time.textContent=format(zone);row.append(label,time);world.append(row)}}catch(err){q('[data-world-times]').replaceChildren();message(err.message,true)}})}
if(kind==='wheel'){let options=[],rotation=0,spinning=false,completion;const wheel=q('[data-wheel]'),spin=q('[data-wheel-spin]'),form=q('[data-extra-form]');const colors=['#b9d2ef','#cec0eb','#baded9','#f1d7bb','#eac2d8','#bddced'];function load(){if(spinning)return;const values=value('wheel-options').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(values.length<2||values.length>24||values.some(s=>s.length>40))throw Error('請輸入 2 到 24 個項目，每項最多 40 字。');options=values;rotation=0;wheel.style.transition='none';wheel.style.transform='rotate(0deg)';wheel.style.background='conic-gradient('+options.map((_,i)=>colors[i%colors.length]+' '+i*360/options.length+'deg '+(i+1)*360/options.length+'deg').join(',')+')';wheel.replaceChildren();options.forEach((s,i)=>{const label=document.createElement('span');label.className='wheel-label';const angle=(i+.5)*Math.PI*2/options.length;label.style.left=(50+33*Math.sin(angle))+'%';label.style.top=(50-33*Math.cos(angle))+'%';label.textContent=s;label.title=s;wheel.append(label)});wheel.setAttribute('aria-label','抽選輪盤，共 '+options.length+' 個項目');spin.disabled=false;message('每個項目的抽中機率相同。')}
 form.addEventListener('submit',e=>{e.preventDefault();try{load()}catch(err){spin.disabled=true;message(err.message,true)}});get('wheel-options').addEventListener('input',()=>{spin.disabled=true;message('名單已修改，請按更新輪盤。')});spin.addEventListener('click',()=>{if(spinning)return;spinning=true;spin.disabled=true;get('wheel-options').disabled=true;form.querySelector('[type=submit]').disabled=true;const selected=randomIndex(options.length),reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;rotation=wheelLanding(rotation,selected,options.length);wheel.style.transition=reduce?'none':'transform 3.4s cubic-bezier(.14,.68,.12,1)';wheel.style.transform='rotate('+rotation+'deg)';message('轉動中…');clearTimeout(completion);completion=setTimeout(()=>{spinning=false;spin.disabled=false;get('wheel-options').disabled=false;form.querySelector('[type=submit]').disabled=false;message('這次選到 '+options[selected]+'。')},reduce?0:3450)});load();window.addEventListener('pagehide',()=>clearTimeout(completion))}
if(kind==='translate'){let translated='';q('[data-extra-form]').addEventListener('submit',async e=>{e.preventDefault();const text=value('translate-text').trim(),from=value('translate-from'),to=value('translate-to'),button=q('[type=submit]');translated='';q('[data-translation-copy]').disabled=true;q('[data-extra-copy]').textContent='';if(!text){message('請先輸入要翻譯的文字。',true);return}if(new TextEncoder().encode(text).length>500){message('原文超過 500 UTF-8 位元組，請縮短句子。',true);return}if(from===to){message(text);translated=text;q('[data-translation-copy]').disabled=false;return}button.disabled=true;message('正在翻譯…');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const params=new URLSearchParams({q:text,langpair:from+'|'+to}),r=await fetch('https://api.mymemory.translated.net/get?'+params,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error();const d=await r.json();if(Number(d.responseStatus)!==200||d.quotaFinished||typeof d.responseData?.translatedText!=='string')throw Error();const decoder=document.createElement('textarea');decoder.innerHTML=d.responseData.translatedText.replaceAll('<','&lt;').replaceAll('>','&gt;');translated=decoder.value;message(translated);q('[data-translation-copy]').disabled=false}catch{message('翻譯服務暫時無法使用或額度已用完，請稍後再試。',true)}finally{clearTimeout(timeout);button.disabled=false}});q('[data-translation-copy]').addEventListener('click',()=>copy(translated,q('[data-extra-copy]')))}
if(kind==='cool-text'){const styles=[['bold','數學粗體'],['sans','無襯線'],['mono','等寬'],['full','全形'],['circle','圈圈字']];const render=()=>{const output=q('[data-cool-results]');output.replaceChildren();for(const[key,name]of styles){const row=document.createElement('div'),label=document.createElement('h2'),text=document.createElement('p'),button=document.createElement('button'),notice=document.createElement('small');row.className='cool-row';label.textContent=name;text.textContent=coolText(value('cool-source'),key);button.textContent='複製';button.className='tool-secondary';button.setAttribute('aria-label','複製'+name);notice.setAttribute('aria-live','polite');button.addEventListener('click',()=>copy(text.textContent,notice));row.append(label,text,button,notice);output.append(row)}};get('cool-source').addEventListener('input',render);render()}
